(() => {
'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='atlas-revolution-detectives-v1',steps=['Examinar una foto','Reconstruir fechas','Comparar propuestas','Explorar lugares','Mi explicación'];
const sources={madero:['INEHRM · Maderismo','https://www.inehrm.gob.mx/es/Constitucion1917/Maderismo'],ayala:['INAH · transcripción del Plan de Ayala','https://www.caracol.inah.gob.mx/index.php/component/content/article/29/72'],guadalupe:['INEHRM · Revolución Constitucionalista','https://www.inehrm.gob.mx/es/Constitucion1917/Revolucion_Constitucionalista'],constitution:['UNAM · Constitución de 1917','https://museodelasconstituciones.unam.mx/constitucion-vigente/'],photo:['Library of Congress · Villa’s men entraining','https://www.loc.gov/pictures/item/2014695704/']};
const events=[['sanluis','5 oct. 1910','Plan de San Luis','Madero formula un programa contra la reelección y convoca al levantamiento; también incluye demandas sociales.','madero'],['ayala','28 nov. 1911','Plan de Ayala','El zapatismo reclama restitución de tierras y medidas agrarias; expresa su ruptura con Madero.','ayala'],['guadalupe','26 mar. 1913','Plan de Guadalupe','Carranza desconoce al gobierno de Huerta y llama a restablecer la legalidad constitucional.','guadalupe'],['constitution','5 feb. 1917','Constitución promulgada en Querétaro','El Congreso Constituyente promulga la nueva Carta. La promulgación no termina todos los conflictos ni asegura cumplimiento inmediato.','constitution']];
const docs=[{title:'Maderismo · Plan de San Luis',ref:'madero',text:'El cambio político frente a la reelección y el fraude electoral fue central. El programa también incluyó demandas sociales: no se reduce a una sola consigna.',task:'¿Qué énfasis caracteriza esta propuesta?',opts:['Desconocer a Huerta en marzo de 1913.','Combatir la reelección y el fraude electoral.','Eliminar todas las demandas sociales.'],correct:1,why:'La demanda política es central en el maderismo, pero no excluye cuestiones sociales.'},{title:'Zapatismo · Plan de Ayala',ref:'ayala',text:'Los artículos 6 y 7 plantean recuperación de bienes de los pueblos despojados y medidas de expropiación con indemnización. Son propuestas del documento, no una descripción de su cumplimiento.',task:'¿Qué demanda agraria aparece en el plan?',opts:['Restitución de tierras y medidas de reparto.','Conservar sin cambios todas las propiedades.','Promulgar la Constitución de 1917 en 1911.'],correct:0,why:'El Plan de Ayala permite estudiar demandas agrarias. Para evaluar su aplicación hacen falta otras fuentes.'},{title:'Constitucionalismo · Plan de Guadalupe de 1913',ref:'guadalupe',text:'En su formulación inicial, el plan desconoce a Huerta y busca restablecer el orden constitucional. Las adiciones y las propuestas posteriores requieren distinguir fechas y documentos.',task:'¿Qué objetivo corresponde al plan inicial de 1913?',opts:['Apoyar el gobierno de Huerta.','Describir una paz duradera ya alcanzada.','Desconocer a Huerta y restablecer la legalidad.'],correct:2,why:'El énfasis inicial es político y constitucional. No debemos atribuirle automáticamente todos los planteamientos posteriores.'}];
const places=[{id:'juarez',name:'Ciudad Juárez',region:'Chihuahua',lon:-106.485,lat:31.739,text:'Escenario de la lucha maderista en 1911. Una ciudad no representa todas las acciones ni todos los proyectos de una región.',question:'¿Qué fase se relaciona con esta referencia?',correct:0},{id:'cuautla',name:'Cuautla',region:'Morelos',lon:-98.95,lat:18.81,text:'Referencia regional vinculada a la acción zapatista. El Plan de Ayala no se identifica aquí como firmado en Cuautla.',question:'¿Qué movimiento se relaciona con esta referencia?',correct:1},{id:'queretaro',name:'Querétaro',region:'Querétaro',lon:-100.392,lat:20.593,text:'Sede del Congreso Constituyente de 1916–1917. Promulgar una Constitución y cumplir sus disposiciones son procesos diferentes.',question:'¿Qué acontecimiento se relaciona con esta referencia?',correct:2}];
const fresh=()=>({version:1,step:0,depth:'explorar',notes:{observe:'',ask:'',similar:'',different:'',claim:'',evidence:'',limit:''},observed:false,order:[],time:false,answers:[null,null,null],place:0,matches:[false,false,false],complete:false});
let state=fresh(),geo=null,mapError=false,persistent=true;
function done(){return [state.observed&&!!state.notes.observe.trim(),state.time,state.answers.every(x=>x!==null),state.matches.every(Boolean),state.complete];}
function restore(){try{const r=JSON.parse(localStorage.getItem(key)||'null');if(!r||r.version!==1)return;for(const k of Object.keys(state.notes))if(typeof r.notes?.[k]==='string')state.notes[k]=r.notes[k].slice(0,5000);if(Number.isInteger(r.step)&&r.step>=0&&r.step<5)state.step=r.step;if(['explorar','comprender','profundizar'].includes(r.depth))state.depth=r.depth;if(Array.isArray(r.order)&&new Set(r.order).size===r.order.length&&r.order.every(id=>events.some(e=>e[0]===id)))state.order=r.order;state.time=r.time===true&&state.order.join(',')===events.map(e=>e[0]).join(',');state.observed=r.observed===true&&!!state.notes.observe.trim();state.answers=docs.map((d,i)=>Number.isInteger(r.answers?.[i])&&r.answers[i]>=0&&r.answers[i]<3?r.answers[i]:null);if(Number.isInteger(r.place)&&r.place>=0&&r.place<3)state.place=r.place;state.matches=places.map((p,i)=>r.matches?.[i]===true);state.complete=r.complete===true&&done().slice(0,4).every(Boolean)&&['claim','evidence','limit'].every(k=>state.notes[k].trim());}catch{persistent=false;}}
function save(){if(!done().slice(0,4).every(Boolean))state.complete=false;try{localStorage.setItem(key,JSON.stringify(state));persistent=true;}catch{persistent=false;}if($('#raProgress'))$('#raProgress').textContent=done().filter(Boolean).length+' de 5 etapas realizadas';if($('#raSave'))$('#raSave').textContent=persistent?'Progreso guardado en este dispositivo.':'No se pudo guardar. El avance permanece mientras esta página esté abierta.';}
const link=id=>`<a href="${sources[id][1]}" target="_blank" rel="noopener">${esc(sources[id][0])}</a>`;
const note=(id,label)=>`<label for="ra-${id}">${label}</label><textarea id="ra-${id}" data-ra-note="${id}" maxlength="5000" rows="3">${esc(state.notes[id])}</textarea>`;
function photo(){return `<h2>Una imagen, muchas preguntas</h2><p>Observa sin atribuir nombres, emociones o motivos a las personas. La fotografía muestra un momento; el catálogo aporta información que no podemos ver por sí solos.</p><figure class="ra-photo"><div id="raImage" tabindex="0" aria-label="Fotografía ampliable; desplázate para observar detalles"><img src="assets/revolution-authentic.webp" alt="Hombres con fusiles y niños junto a un vagón ferroviario en una fotografía histórica"></div><label>Ampliación <input id="raZoom" type="range" min="1" max="3" step=".25" value="1"><output id="raZoomValue">1×</output></label><figcaption>Bain News Service / Library of Congress · LC-DIG-ggbain-15727. El catálogo indica que no se conocen restricciones de publicación.</figcaption></figure><details><summary>Consultar la ficha y sus límites</summary><p>Título: Villa’s men entraining. Fecha registrada: 23 de marzo de 1914, de creación o publicación posterior por Bain. El catálogo identifica soldados bajo el mando de Villa, probablemente en Gómez Palacio, Durango. La localización es probable; la imagen no demuestra el papel de cada niño ni la opinión de todas las personas retratadas.</p>${link('photo')}</details><details><summary>Pista de observación</summary><p>Busca el vagón, la disposición de las personas y los objetos que llevan. Separa «veo un fusil» de «sé por el catálogo a qué fuerzas se vinculan».</p></details>${note('observe',state.depth==='explorar'?'Describe un detalle visible':state.depth==='comprender'?'Describe un detalle y distingue un dato del catálogo':'Separa observación, identificación de catálogo y una inferencia; conserva la incertidumbre')}${note('ask','¿Qué no puedes saber con esta fotografía?')}<button id="raObserve" class="atlas-button">Registrar observación</button><p id="raObserveFeedback" role="status">${state.observed?'Observación registrada.':''}</p>`;}
function timeline(){return `<h2>Reconstruye cuatro referencias</h2><p>Selecciona de la más antigua a la más reciente. Los planes son propuestas políticas; una fecha no demuestra que se cumplieron sus demandas.</p><div class="ga-pool">${[2,0,3,1].map(i=>events[i]).filter(e=>!state.order.includes(e[0])).map(e=>`<button data-ra-event="${e[0]}"><strong>${e[1]}</strong><span>${e[2]}</span></button>`).join('')}</div><ol class="ga-timeline">${state.order.map(id=>{const e=events.find(e=>e[0]===id);return `<li><strong>${e[1]} · ${e[2]}</strong><p>${e[3]}</p>${link(e[4])}</li>`;}).join('')}</ol><div class="ga-actions"><button id="raUndo" class="atlas-outline" ${state.order.length?'':'disabled'}>Quitar la última</button><button id="raTimeCheck" class="atlas-button" ${state.order.length===4?'':'disabled'}>Comprobar orden</button></div><p id="raTimeFeedback" role="status">${state.time?'Orden correcto: 1910, 1911, 1913 y 1917.':''}</p><a href="#historietas/revolucion">Explorar las viñetas de la Revolución</a>`;}
function compare(){return `<h2>Propuestas que coinciden y divergen</h2><p>Estas tarjetas son síntesis educativas, no citas literales. Sus énfasis no describen a cada integrante de un movimiento ni todas sus etapas.</p>${docs.map((d,i)=>`<article class="ga-question"><h3>${d.title}</h3><p>${d.text}</p>${link(d.ref)}<h4>${d.task}</h4><div>${d.opts.map((o,j)=>`<button data-ra-answer="${i}" data-option="${j}" ${state.answers[i]!==null?'disabled':''} class="${state.answers[i]!==null&&j===d.correct?'ga-correct':''}">${o}</button>`).join('')}</div><p role="status">${state.answers[i]!==null?`${state.answers[i]===d.correct?'Respuesta apoyada.':'Revisa la opción señalada.'} ${d.why}`:''}</p></article>`).join('')}${note('similar','Una coincidencia entre dos propuestas')}${note('different',state.depth==='profundizar'?'Una diferencia: identifica fecha, destinatario y problema; ¿qué voces quedan fuera?':'Una diferencia entre sus prioridades')}<p>La Revolución también involucró villistas, magonistas, trabajadores, mujeres, comunidades y otros actores. Estas tres tarjetas son una selección para comparar documentos.</p>`;}
const project=([lon,lat])=>[(lon+118.5)*23,(33.5-lat)*25];
function path(g){const polys=g.type==='Polygon'?[g.coordinates]:g.coordinates;return polys.map(p=>p.map(r=>r.map((c,i)=>{const [x,y]=project(c);return `${i?'L':'M'}${x.toFixed(2)},${y.toFixed(2)}`;}).join('')+'Z').join('')).join('');}
function map(){const p=places[state.place];return `<h2>Relaciona lugares y procesos</h2><p>Usamos límites estatales de referencia del mapa de Atlas para orientarnos. No representan fronteras de 1910 ni áreas de control militar. Las posiciones de los puntos son aproximadas.</p><div class="ra-map-layout"><div>${geo?`<svg viewBox="0 0 750 500" class="ra-map" role="group" aria-label="Mapa de México con Ciudad Juárez, Cuautla y Querétaro"><title>Tres lugares de la Revolución</title>${geo.features.map(f=>`<path d="${path(f.geometry)}"/>`).join('')}${places.map((p,i)=>{const [x,y]=project([p.lon,p.lat]);return `<g data-ra-map="${i}" tabindex="0" role="button" aria-label="Explorar ${p.name}"><circle cx="${x}" cy="${y}" r="12" class="${state.place===i?'ra-selected':''}"/><text x="${x}" y="${y+4}" text-anchor="middle">${i+1}</text></g>`;}).join('')}</svg>`:mapError?'<p>No se pudo cargar la cartografía. Puedes usar la lista de lugares.</p><button id="raMapRetry" class="atlas-outline">Reintentar mapa</button>':'<p>Cargando cartografía…</p>'}<div class="ga-actions">${places.map((p,i)=>`<button data-ra-place="${i}" class="atlas-outline" aria-pressed="${state.place===i}">${i+1}. ${p.name}${state.matches[i]?' · Relacionado':''}</button>`).join('')}</div></div><article class="ra-place"><p class="eyebrow">${p.region}</p><h3>${p.name}</h3><p>${p.text}</p><h4>${p.question}</h4><div class="ra-place-options">${['Lucha maderista de 1911','Acción zapatista en Morelos','Congreso Constituyente de 1916–1917'].map((l,i)=>`<button data-ra-match="${i}" class="atlas-outline">${l}</button>`).join('')}</div><p id="raMapFeedback" role="status">${state.matches[state.place]?'Relación registrada. Consulta otro lugar.':''}</p><details><summary>Pista</summary><p>${['Esta ciudad fronteriza tuvo un papel clave durante la fase inicial de 1911.','Relaciona la demanda agraria con el movimiento del sur.','Aquí se reunió el Congreso que discutió la nueva Constitución.'][state.place]}</p></details><a href="#ruta/revolucion">Consultar la ruta y sus fuentes</a></article></div>`;}
function finish(){return `<h2>¿Por qué buscaban cosas distintas?</h2><p>${state.depth==='explorar'?'Conversa o dibuja primero. Después escribe una frase en cada espacio.':state.depth==='comprender'?'Compara dos propuestas, un problema que buscaban resolver y una evidencia.':'Considera intereses, regiones, cambios de alianzas y fechas. Distingue programa, práctica y memoria.'}</p>${note('claim','Mi explicación: una coincidencia y una diferencia entre proyectos')}${note('evidence','Mi evidencia: identifica un documento, su fecha y una propuesta concreta')}${note('limit','Mi límite: qué no sabemos y qué otra fuente o voz consultaríamos')}<button id="raFinish" class="atlas-button">Completar investigación</button><p id="raFinishFeedback" role="status">${state.complete?'Investigación completada. Revisa tu explicación con otra persona.':''}</p><details id="raSummary"><summary>Mi expediente y fuentes</summary><p>Observación: ${esc(state.notes.observe)}</p><p>Pregunta: ${esc(state.notes.ask)}</p><p>Coincidencia: ${esc(state.notes.similar)}</p><p>Diferencia: ${esc(state.notes.different)}</p><p>Cronología: ${state.order.map(id=>esc(events.find(e=>e[0]===id)[1])).join(' · ')}</p><p>Lugares relacionados: ${places.filter((p,i)=>state.matches[i]).map(p=>p.name).join(', ')}</p><ul>${Object.keys(sources).map(id=>`<li>${link(id)}</li>`).join('')}</ul></details><button id="raPrint" class="atlas-outline">Imprimir mi expediente</button><p>El texto no recibe una calificación automática. Una fotografía no prueba acuerdo entre todos los revolucionarios; un programa tampoco demuestra cumplimiento.</p><a href="#ruta/revolucion">Continuar en la ruta de la Revolución</a>`;}
function render(){const h=$('#revolutionAdventure');if(!h)return;h.innerHTML=`<header class="ga-top"><div><p class="eyebrow">INVESTIGACIÓN · 30–45 MIN</p><h1>Detectives de la Revolución</h1></div><button id="raProject" class="atlas-outline">Proyectar</button></header><div class="ga-toolbar"><label for="raDepth">Profundidad</label><select id="raDepth">${[['explorar','Explorar'],['comprender','Comprender'],['profundizar','Profundizar']].map(([id,l])=>`<option value="${id}" ${state.depth===id?'selected':''}>${l}</option>`).join('')}</select><span id="raProgress">${done().filter(Boolean).length} de 5 etapas realizadas</span><button id="raReset" class="atlas-outline">Reiniciar investigación</button></div><nav class="ga-steps" aria-label="Etapas de investigación">${steps.map((l,i)=>`<button data-ra-step="${i}" aria-current="${state.step===i?'step':'false'}">${i+1}. ${l}${done()[i]?' · Realizada':''}</button>`).join('')}</nav><p id="raSave" class="ga-caption">${persistent?'Progreso guardado en este dispositivo.':'No se pudo guardar. El avance permanece mientras esta página esté abierta.'}</p><div class="ga-stage">${[photo,timeline,compare,map,finish][state.step]()}</div><div class="ga-actions ga-navigation"><button id="raPrev" class="atlas-outline" ${state.step===0?'disabled':''}>Etapa anterior</button><button id="raNext" class="atlas-button" ${state.step===4?'disabled':''}>Siguiente etapa</button></div>`;bind();}
function go(i){state.step=i;save();render();$('#revolutionAdventure .ga-stage h2')?.setAttribute('tabindex','-1');$('#revolutionAdventure .ga-stage h2')?.focus();}
function bind(){
 $('#raDepth').onchange=e=>{state.depth=e.target.value;save();render();};$('#raProject').onclick=()=>$('#projectorBtn').click();$('#raReset').onclick=()=>{state=fresh();save();render();};$('#raPrev').onclick=()=>{if(state.step>0)go(state.step-1);};$('#raNext').onclick=()=>{if(state.step<4)go(state.step+1);};$$('[data-ra-step]').forEach(b=>b.onclick=()=>go(+b.dataset.raStep));
 $$('[data-ra-note]').forEach(n=>n.oninput=()=>{state.notes[n.dataset.raNote]=n.value;if(n.dataset.raNote==='observe')state.observed=false;state.complete=false;save();});if($('#raZoom'))$('#raZoom').oninput=e=>{$('#raImage img').style.width=Number(e.target.value)*100+'%';$('#raZoomValue').textContent=e.target.value+'×';};if($('#raObserve'))$('#raObserve').onclick=()=>{state.observed=!!state.notes.observe.trim();save();$('#raObserveFeedback').textContent=state.observed?'Observación registrada.':'Escribe un detalle antes de registrar.';};
 $$('[data-ra-event]').forEach(b=>b.onclick=()=>{state.order.push(b.dataset.raEvent);state.time=false;save();render();});if($('#raUndo'))$('#raUndo').onclick=()=>{state.order.pop();state.time=false;save();render();};if($('#raTimeCheck'))$('#raTimeCheck').onclick=()=>{state.time=state.order.join(',')===events.map(e=>e[0]).join(',');save();$('#raTimeFeedback').textContent=state.time?'Orden correcto: 1910, 1911, 1913 y 1917.':'Revisa: San Luis precede a Ayala; Guadalupe responde al gobierno de Huerta en 1913; la Constitución se promulga en 1917.';};
 $$('[data-ra-answer]').forEach(b=>b.onclick=()=>{const i=+b.dataset.raAnswer;if(state.answers[i]!==null)return;state.answers[i]=+b.dataset.option;save();render();});
 const choose=i=>{state.place=i;save();render();};$$('[data-ra-place],[data-ra-map]').forEach(b=>{b.onclick=()=>choose(+(b.dataset.raPlace??b.dataset.raMap));if(b.dataset.raMap!==undefined)b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.onclick();}};});$$('[data-ra-match]').forEach(b=>b.onclick=()=>{const ok=+b.dataset.raMatch===places[state.place].correct;state.matches[state.place]=ok;save();$('#raMapFeedback').textContent=ok?'Relación apoyada. Consulta otro lugar.':'Revisa la ficha y la pista; puedes volver a intentarlo.';});if($('#raMapRetry'))$('#raMapRetry').onclick=loadMap;
 if($('#raFinish'))$('#raFinish').onclick=()=>{if(!['claim','evidence','limit'].every(k=>state.notes[k].trim())){$('#raFinishFeedback').textContent='Completa explicación, evidencia y límite.';return;}if(!done().slice(0,4).every(Boolean)){$('#raFinishFeedback').textContent='Revisa las etapas pendientes: foto, cronología, tres propuestas y tres lugares.';return;}state.complete=true;save();render();};if($('#raPrint'))$('#raPrint').onclick=()=>{$('#raSummary').open=true;window.print();};
}
async function loadMap(){mapError=false;try{const r=await fetch('data/states.geojson');if(!r.ok)throw Error('map');geo=await r.json();if(!Array.isArray(geo.features))throw Error('map');}catch{mapError=true;}if(state.step===3)render();}
restore();render();loadMap();window.AtlasRevolutionAdventure={reload:()=>{state=fresh();persistent=true;restore();render();}};
})();
